def get_adjacent_states(grid):
    rows = len(grid)
    cols = len(grid[0])

    adjacent_states = []

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] != 'X':
                # Check all four directions (up, down, left, right) for valid movements
                if i > 0 and grid[i-1][j] == 'X': 
                    adjacent_states.append([i-1, j])  
                if i < rows - 1 and grid[i+1][j] == 'X':
                    adjacent_states.append([i+1, j])
                if j > 0 and grid[i][j-1] == 'X':
                    adjacent_states.append([i, j-1])
                if j < cols - 1 and grid[i][j+1] == 'X':
                    adjacent_states.append([i, j+1])

    return adjacent_states

